BEGIN;
UPDATE public.world_state SET world_date='2027-09-01',world_time='08:00',time_speed=0,clock_started_at=now() WHERE id=1;
DO $$
DECLARE student uuid; worker uuid; career uuid; uid uuid; university uuid; home uuid; aid uuid; job uuid; workplace uuid; balance_before integer; count_before integer; snapshot jsonb; snapshot_after jsonb;
BEGIN
uid:=gen_random_uuid(); PERFORM set_config('request.jwt.claim.sub',uid::text,true);
student:=public.create_character('Test','Étudiant',18,'lyon','student','{}');
PERFORM public.enroll_studies('law');
IF NOT EXISTS(SELECT 1 FROM public.study_enrollments WHERE character_id=student AND field_id='law') THEN RAISE EXCEPTION 'Inscription absente'; END IF;
SELECT location_id INTO university FROM public.study_enrollments WHERE character_id=student;
IF NOT EXISTS(SELECT 1 FROM public.locations WHERE id=university AND city_id='lyon' AND kind='universite') THEN RAISE EXCEPTION 'Université incorrecte'; END IF;
SELECT id INTO aid FROM public.activities WHERE character_id=student AND type='course' AND start_time::date='2027-09-01';
IF aid IS NULL THEN RAISE EXCEPTION 'Cours absent de l’agenda'; END IF;
PERFORM public.move_character(university);
BEGIN PERFORM public.start_life_activity(_activity_id=>aid); RAISE EXCEPTION 'TEST_FAIL cours démarré trop tôt'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST_FAIL%' THEN RAISE; END IF; END;
UPDATE public.world_state SET world_time='09:10' WHERE id=1;
PERFORM public.start_life_activity(_activity_id=>aid);
IF (SELECT energy FROM public.characters WHERE id=student)<>80 THEN RAISE EXCEPTION 'Cours doit consommer 20 énergie'; END IF;
PERFORM public.daily_life_state();
IF (SELECT progress FROM public.study_enrollments WHERE character_id=student)<>0 THEN RAISE EXCEPTION 'Cours validé instantanément'; END IF;
SELECT location_id INTO home FROM public.character_housing WHERE character_id=student;
BEGIN PERFORM public.move_character(home); RAISE EXCEPTION 'TEST_FAIL déplacement pendant cours'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST_FAIL%' THEN RAISE; END IF; END;
UPDATE public.world_state SET world_time='11:10' WHERE id=1;
PERFORM public.daily_life_state();
IF (SELECT progress FROM public.study_enrollments WHERE character_id=student)<>15 OR (SELECT status FROM public.activities WHERE id=aid)<>'completed' THEN RAISE EXCEPTION 'Cours sans progression'; END IF;
IF (SELECT (skills->>'Raisonnement juridique')::integer FROM public.study_enrollments WHERE character_id=student)<>15 THEN RAISE EXCEPTION 'Compétence incorrecte'; END IF;
PERFORM public.move_character(home); PERFORM public.start_life_activity('rest');
UPDATE public.world_state SET world_time='11:40' WHERE id=1; PERFORM public.daily_life_state();
IF (SELECT energy FROM public.characters WHERE id=student)<>100 THEN RAISE EXCEPTION 'Repos non plafonné à 100'; END IF;
SELECT balance INTO balance_before FROM public.accounts WHERE character_id=student;
PERFORM public.start_life_activity('eat');
IF (SELECT balance FROM public.accounts WHERE character_id=student)<>balance_before-8 THEN RAISE EXCEPTION 'Repas non débité'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.transactions tr JOIN public.accounts ac ON ac.id=tr.account_id WHERE ac.character_id=student AND tr.amount=-8) THEN RAISE EXCEPTION 'Transaction repas absente'; END IF;
UPDATE public.world_state SET world_time='12:00' WHERE id=1; PERFORM public.daily_life_state(); PERFORM public.pay_housing();
IF (SELECT balance FROM public.accounts WHERE character_id=student)<>balance_before-18 THEN RAISE EXCEPTION 'Logement incorrect'; END IF;
BEGIN PERFORM public.pay_housing(); RAISE EXCEPTION 'TEST_FAIL double logement'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST_FAIL%' THEN RAISE; END IF; END;
snapshot:=public.daily_life_state(); PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
BEGIN PERFORM public.daily_life_state(); RAISE EXCEPTION 'TEST_FAIL accès autre utilisateur'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST_FAIL%' THEN RAISE; END IF; END;
PERFORM set_config('request.jwt.claim.sub',uid::text,true); snapshot_after:=public.daily_life_state();
IF snapshot<>snapshot_after THEN RAISE EXCEPTION 'État étudiant non persistant'; END IF;
UPDATE public.world_state SET world_time='08:00' WHERE id=1;
uid:=gen_random_uuid(); PERFORM set_config('request.jwt.claim.sub',uid::text,true);
worker:=public.create_character('Test','Actif',18,'lyon','young_worker','{}');
PERFORM public.daily_life_state();
SELECT id,location_id INTO job,workplace FROM public.jobs WHERE city_id='lyon' AND title='Assistant administratif' LIMIT 1;
PERFORM public.apply_job(job);
IF EXISTS(SELECT 1 FROM public.employments WHERE character_id=worker) THEN RAISE EXCEPTION 'Emploi instantané'; END IF;
UPDATE public.world_state SET world_time='08:01' WHERE id=1; PERFORM public.daily_life_state();
IF NOT EXISTS(SELECT 1 FROM public.employments WHERE character_id=worker AND job_id=job) THEN RAISE EXCEPTION 'Candidature non acceptée'; END IF;
PERFORM public.move_character(workplace);
SELECT id INTO aid FROM public.activities WHERE character_id=worker AND type='work' AND start_time::date='2027-09-01';
SELECT balance INTO balance_before FROM public.accounts WHERE character_id=worker;
PERFORM public.start_life_activity(_activity_id=>aid);
IF (SELECT energy FROM public.characters WHERE id=worker)<>70 THEN RAISE EXCEPTION 'Travail doit consommer 30 énergie'; END IF;
PERFORM public.daily_life_state(); IF (SELECT balance FROM public.accounts WHERE character_id=worker)<>balance_before THEN RAISE EXCEPTION 'Salaire instantané'; END IF;
UPDATE public.world_state SET world_time='12:01' WHERE id=1; PERFORM public.daily_life_state();
IF (SELECT balance FROM public.accounts WHERE character_id=worker)<>balance_before+80 THEN RAISE EXCEPTION 'Salaire 1600/20 incorrect'; END IF;
IF (SELECT progress FROM public.employments WHERE character_id=worker)<>10 THEN RAISE EXCEPTION 'Progression travail incorrecte'; END IF;
SELECT count(*) INTO count_before FROM public.transactions tr JOIN public.accounts ac ON ac.id=tr.account_id WHERE ac.character_id=worker AND tr.amount=80;
IF count_before<>1 THEN RAISE EXCEPTION 'Transaction salaire absente'; END IF;
PERFORM public.daily_life_state(); IF (SELECT balance FROM public.accounts WHERE character_id=worker)<>balance_before+80 THEN RAISE EXCEPTION 'Double versement'; END IF;
BEGIN PERFORM public.start_life_activity('work'); RAISE EXCEPTION 'TEST_FAIL deuxième vacation'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST_FAIL%' THEN RAISE; END IF; END;
snapshot:=public.daily_life_state(); PERFORM set_config('request.jwt.claim.sub','',true); PERFORM set_config('request.jwt.claim.sub',uid::text,true);
IF snapshot<>public.daily_life_state() THEN RAISE EXCEPTION 'État actif non persistant'; END IF;
UPDATE public.world_state SET world_time='08:00' WHERE id=1;
uid:=gen_random_uuid(); PERFORM set_config('request.jwt.claim.sub',uid::text,true);
career:=public.create_character('Test','Carrière',22,'lyon','early_career','{}');
SELECT id,location_id INTO job,workplace FROM public.jobs WHERE city_id='lyon' AND title='Développeur junior' LIMIT 1;
PERFORM public.apply_job(job); UPDATE public.world_state SET world_time='08:01' WHERE id=1; PERFORM public.daily_life_state();
IF NOT EXISTS(SELECT 1 FROM public.employments WHERE character_id=career AND job_id=job) THEN RAISE EXCEPTION 'Début carrière refusé'; END IF;
PERFORM public.move_character(workplace); SELECT id INTO aid FROM public.activities WHERE character_id=career AND type='work' AND start_time::date='2027-09-01';
SELECT balance INTO balance_before FROM public.accounts WHERE character_id=career;
PERFORM public.start_life_activity(_activity_id=>aid); UPDATE public.world_state SET world_time='12:01' WHERE id=1; PERFORM public.daily_life_state();
IF (SELECT balance FROM public.accounts WHERE character_id=career)<>balance_before+110 OR (SELECT progress FROM public.employments WHERE character_id=career)<>10 THEN RAISE EXCEPTION 'Salaire/progression carrière incorrect'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.character_housing WHERE character_id=career AND type_id='flat') THEN RAISE EXCEPTION 'Logement carrière absent'; END IF;
IF has_table_privilege('authenticated','public.activities','UPDATE') OR has_table_privilege('authenticated','public.characters','UPDATE') OR has_table_privilege('authenticated','public.accounts','UPDATE') OR has_table_privilege('authenticated','public.employments','INSERT') THEN RAISE EXCEPTION 'Écriture directe autorisée'; END IF;
END $$;
SELECT 'DAILY_LIFE_RULES_OK';
ROLLBACK;